#include <exchanges/binance/model/StatisticsTicker.hpp>
#include <rapidjson/document.h>
#include <gtest/gtest.h>

TEST(tickerEventEvent, testDeserialize) {
    const char* json = R"({
  "stream": "btcusdt@ticker",
  "data": {
    "e": "24hrTicker",
    "E": 1733571480276,
    "s": "BTCUSDT",
    "p": "1596.93000000",
    "P": "1.631",
    "w": "99792.67456836",
    "x": "97937.32000000",
    "c": "99534.24000000",
    "Q": "0.00029000",
    "b": "99534.23000000",
    "B": "3.74597000",
    "a": "99534.24000000",
    "A": "1.62546000",
    "o": "97937.31000000",
    "h": "101898.99000000",
    "l": "97512.26000000",
    "v": "33061.13123000",
    "q": "3299258709.69723350",
    "O": 1733485080275,
    "C": 1733571480275,
    "F": 4217719181,
    "L": 4223139000,
    "n": 5419820
  }
})";

    Binance::StatisticsTickerEvent event;
    rapidjson::Document d;
    d.Parse(json);
    auto flag = event.deserialize(d);
    EXPECT_EQ(flag, true);
    EXPECT_EQ(event.stream, "btcusdt@ticker");
    EXPECT_EQ(event.ticker.eventType, "24hrTicker");
    EXPECT_EQ(event.ticker.eventTime, 1733571480276);
    EXPECT_EQ(event.ticker.symbol, "BTCUSDT");
    EXPECT_EQ(event.ticker.priceChange, "1596.93000000");
    EXPECT_EQ(event.ticker.priceChangePercent, "1.631");
    EXPECT_EQ(event.ticker.weightedAveragePrice, "99792.67456836");
    EXPECT_EQ(event.ticker.firstTradePriceBefore24H, "97937.32000000");
    EXPECT_EQ(event.ticker.lastPrice, "99534.24000000");
    EXPECT_EQ(event.ticker.lastQuantity, "0.00029000");
    EXPECT_EQ(event.ticker.bestBidPrice, "99534.23000000");
    EXPECT_EQ(event.ticker.bestBidQuantity, "3.74597000");
    EXPECT_EQ(event.ticker.bestAskPrice, "99534.24000000");
    EXPECT_EQ(event.ticker.bestAskQuantity, "1.62546000");
    EXPECT_EQ(event.ticker.openPrice, "97937.31000000");
    EXPECT_EQ(event.ticker.highPrice, "101898.99000000");
    EXPECT_EQ(event.ticker.lowPrice, "97512.26000000");
    EXPECT_EQ(event.ticker.baseAssetVolume, "33061.13123000");
    EXPECT_EQ(event.ticker.quoteAssetVolume, "3299258709.69723350");
    EXPECT_EQ(event.ticker.statisticsOpenTime, 1733485080275);
    EXPECT_EQ(event.ticker.statisticsCloseTime, 1733571480275);
    EXPECT_EQ(event.ticker.firstTradeID, 4217719181);
    EXPECT_EQ(event.ticker.lastTradeID, 4223139000);
    EXPECT_EQ(event.ticker.totalTradeNumbers, 5419820);
}

