    Binance::AllStatisticsTickersEvent event;
    rapidjson::Document d;
    d.Parse(json);
    auto flag = event.deserialize(d);
    EXPECT_EQ(flag, true);
    EXPECT_EQ(event.stream, "!ticker@arr");
    EXPECT_EQ(event.tickers.size(), 527);
    EXPECT_EQ(event.tickers[0].eventType, "24hrTicker");
